#include <algorithm>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

using Trip = std::pair<int, std::string>;

int main() {
    std::vector<Trip> trips;
    trips.emplace_back(320, "Denver");
    trips.emplace_back(85, "Boulder");
    trips.emplace_back(1200, "Chicago");
    trips.emplace_back(540, "Omaha");

    std::sort(trips.begin(), trips.end());

    const Trip& closest = trips.front();
    const Trip& farthest = trips.back();
    std::cout << "Closest: " << closest.first << ' ' << closest.second << '\n';
    std::cout << "Farthest: " << farthest.first << ' ' << farthest.second << '\n';

    const std::pair range{closest.first, farthest.first};
    std::cout << "Range: " << range.first << " to " << range.second << '\n';
    return 0;
}

