#include <algorithm>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <string>
#include <tuple>
#include <utility>
#include <vector>

std::pair<int, int> minMax(const std::vector<int>& v) {
    // v must not be empty: v[0] on an empty vector is undefined behavior
    int lo = v[0];
    int hi = v[0];
    for (int x : v) {
        lo = std::min(lo, x);
        hi = std::max(hi, x);
    }
    return {lo, hi};
}

std::tuple<int, int, double> stats(const std::vector<int>& v) {
    const int count = static_cast<int>(v.size());
    const int sum = std::accumulate(v.begin(), v.end(), 0);
    return {count, sum, static_cast<double>(sum) / count};
}

int main() {
    const std::vector<int> scores = {72, 95, 88, 64, 83};
    const auto [lo, hi] = minMax(scores);
    std::cout << "Min " << lo << ", max " << hi << '\n';

    const auto [count, sum, mean] = stats(scores);
    std::cout << std::fixed << std::setprecision(1);
    std::cout << count << " scores, sum " << sum << ", mean " << mean << '\n';

    std::vector<std::pair<std::string, int>> entries = {{"Ava", 78}, {"Ben", 91}, {"Lia", 85}};
    for (auto& [name, score] : entries) {
        score += 5;
    }
    for (const auto& [name, score] : entries) {
        std::cout << name << ' ' << score << '\n';
    }
    return 0;
}

