#include <algorithm>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <string>
#include <tuple>
#include <utility>
#include <vector>

std::pair<int, int> divmod(int a, int b) {
    return {a / b, a % b};
}

std::tuple<double, double, double> summary(const std::vector<double>& v) {
    // v must not be empty
    double lo = v[0];
    double hi = v[0];
    for (double x : v) {
        lo = std::min(lo, x);
        hi = std::max(hi, x);
    }
    const double total = std::accumulate(v.begin(), v.end(), 0.0);
    return {lo, hi, total / static_cast<double>(v.size())};
}

int main() {
    const std::vector<double> temps = {12.5, 18.0, 9.5, 22.0};
    std::vector<std::pair<std::string, double>> cities = {{"Oslo", 4.0}, {"Cairo", 30.0}, {"Lima", 18.5}};
    std::cout << std::fixed << std::setprecision(1);

    const auto [q, r] = divmod(17, 5);
    std::cout << "17 / 5 = " << q << " remainder " << r << '\n';

    const auto [low, high, average] = summary(temps);
    std::cout << "Low " << low << ", high " << high << ", average " << average << '\n';

    for (auto& [city, temp] : cities) {
        temp = temp * 9.0 / 5.0 + 32.0;
    }
    for (const auto& [city, temp] : cities) {
        std::cout << city << ' ' << temp << '\n';
    }
    return 0;
}
